import sys
from collections import deque

data = sys.stdin.read().split()
n, m = int(data[0]), int(data[1])
edges = [(int(data[2 + 2 * i]), int(data[3 + 2 * i])) for i in range(m)]
best = 10 ** 9
for k in range(m):
    a, b = edges[k]
    adj = [[] for _ in range(n + 1)]
    for j in range(m):
        if j != k:
            u, v = edges[j]
            adj[u].append(v)
            adj[v].append(u)
    # shortest path from a to b without the edge (a, b); together with that edge it closes a cycle
    dist = {a: 0}
    q = deque([a])
    while q:
        u = q.popleft()
        for v in adj[u]:
            if v not in dist:
                dist[v] = dist[u] + 1
                q.append(v)
    if b in dist and dist[b] + 1 < best:
        best = dist[b] + 1
print(best)

